export function siteCategories(site) {
  const hay = [site.name, site.focus, site.notes, site.language].join(" ");
  const cats = RULES.filter((r) => r.re.test(hay)).map((r) => r.cat);
  for (const extra of OVERRIDES[site.name] || []) {
    if (!cats.includes(extra)) cats.push(extra);
  }
  // Keep the site's own category order stable: the CATEGORIES order.
  return CATEGORIES.map((c) => c.id).filter((id) => cats.includes(id));
}

// Tool-count parsing for the /sites size filter. The data's tools
// field is a free-text string ("~200", "3,938 (live verify)",
// "n/v", "Engine", "Dev set", ...). Take the largest number found;
// no number (or "n/v") means the count is not stated.
export function parseToolCount(tools) {
  if (!tools || /n\/v/i.test(tools)) return null;
  const nums = String(tools).match(/[\d,]+/g);
  if (!nums) return null;
  return Math.max(...nums.map((n) => parseInt(n.replace(/,/g, ""), 10)));
}

export function sizeBucket(site) {
  const n = parseToolCount(site.tools);
  if (n === null || Number.isNaN(n)) return "unknown";
  if (n < 50) return "small";
  if (n <= 500) return "medium";
  return "large";
}

export const SIZE_BUCKETS = [
  { id: "all", label: "All sizes" },
  { id: "small", label: "Fewer than 50 tools" },
  { id: "medium", label: "50 to 500 tools" },
  { id: "large", label: "More than 500 tools" },
  { id: "unknown", label: "Tool count not stated" }
];

export function sizeLabel(site) {
  const n = parseToolCount(site.tools);
  if (n === null || Number.isNaN(n)) return "Tool count not listed";
  return `${site.tools} tools`;
}
